css:
.np-shell{font:14px/1.45 system-ui,sans-serif;color:#172033;background:#fafafa;border:1px solid #e2e8f0;border-radius:16px;padding:20px}.np-shell h2{margin:2px 0 4px}.np-shell header>p:last-child{margin:0;color:#64748b}.np-kicker{margin:0;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-size:11px}
.np-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.np-proto{background:white;border:1px solid #dfe3ea;border-radius:14px;overflow:hidden}.np-label{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid #e5e7eb}.np-label strong{display:grid;place-items:center;width:26px;height:26px;border-radius:50%;background:#111827;color:white}.np-label span{font-weight:650}
.np-sidebar-demo{display:grid;grid-template-columns:128px 1fr;min-height:220px}.np-side-nav{padding:12px;background:#111827;display:flex;flex-direction:column;gap:7px}.np-side-nav button{border:0;border-radius:8px;padding:9px 10px;text-align:left;background:transparent;color:#dbe4f0;cursor:pointer}.np-side-nav button.active{background:#334155;color:white;font-weight:700}
.np-top-nav{display:flex;gap:4px;padding:10px 12px 0;border-bottom:1px solid #e5e7eb}.np-top-nav button{border:0;border-bottom:3px solid transparent;background:transparent;padding:9px 12px;cursor:pointer;color:#64748b}.np-top-nav button.active{color:#0f172a;border-bottom-color:#2563eb;font-weight:700}
.np-preview{padding:18px;min-height:160px}.np-preview h3{margin:0 0 8px}.np-preview p{margin:0;color:#64748b}.np-preview .np-sample{margin-top:14px;border:1px solid #e2e8f0;border-radius:9px;padding:10px;background:#f8fafc}
@media(max-width:780px){.np-grid{grid-template-columns:1fr}}

js:
const sections=['Overview','Tasks','Notes'];
const copy={
 Overview:['Workspace overview','See the project summary, current activity, and what needs attention.'],
 Tasks:['Task list','Review assigned work, status, and upcoming due dates.'],
 Notes:['Project notes','Keep decisions and working notes close to the project.']
};
const state={A:'Overview',B:'Overview'};
function buttons(which,cls){
  return sections.map(s=>`<button type="button" data-proto="${which}" data-section="${s}" class="${state[which]===s?'active':''}">${s}</button>`).join('');
}
function preview(which){
  const s=state[which],[title,body]=copy[s];
  const el=root.querySelector(`[data-preview="${which}"]`);
  el.innerHTML=`<h3>${title}</h3><p>${body}</p><div class="np-sample"><strong>${s}</strong><br>This preview changed inside option ${which}.</div>`;
}
function render(){
  root.querySelector('.np-side-nav').innerHTML=buttons('A','side');
  root.querySelector('.np-top-nav').innerHTML=buttons('B','top');
  preview('A');preview('B');
}
root.addEventListener('click',e=>{
  const b=e.target.closest('button[data-proto]'); if(!b)return;
  state[b.dataset.proto]=b.dataset.section; render();
  api.log(2,`Prototype ${b.dataset.proto}: ${b.dataset.section}`);
});
render();
